        // Restrict domain to avoid overflows in setup and to ensure the burn is feasible.
        vm.assume(burner != address(0));
        vm.assume(initialOwnerBalance >= burnAmount);
        // The mintToken function will add to totalSupply and balance; we bound to a reasonable max to avoid overflow.
        vm.assume(initialOwnerBalance <= type(uint256).max / 2);
        vm.assume(burnAmount <= initialOwnerBalance);

        // Set up: owner mints tokens to themselves, then transfers to burner.
        // We need the owner to have funds to mint and transfer. The contract constructor gives owner
        // totalSupply = initialSupply * 10**decimals. decimals == 0. initialSupply was 0.
        // So the owner starts with 0 tokens. We mint tokens to the owner for setup.
        uint256 mintAmount = initialOwnerBalance;
        // mintToken is onlyOwner, so we prank owner.
        vm.prank(address(this)); // setUp runs as the test contract, which deployed c, so it's owner.
        c.mintToken(address(this), mintAmount);

        // Transfer minted tokens to the burner
        vm.prank(address(this));
        c.transfer(burner, mintAmount);

        // record totalSupply before burn
        uint256 totalSupplyBefore = c.totalSupply();

        // burner burns some amount
        vm.prank(burner);
        c.burn(burnAmount);

        // compute sum of known balances (only burner is relevant, others are 0, but we get all)
        uint256 sumBalances = c.balanceOf(burner) + c.balanceOf(address(this));
        // In a correct contract, totalSupply must be strictly less than sum of balances?
        // Actually totalSupply should equal sumBalances, but after burn totalSupply is reduced.
        // Since only burner's balance decreased, sumBalances now equals (mintAmount - burnAmount) + 0.
        // totalSupplyBefore was mintAmount. After correct burn, totalSupply = mintAmount - burnAmount = sumBalances.
        // With bug, totalSupply remains mintAmount, which is > sumBalances.
        // So rule: totalSupply <= sumBalances (in fact they must be equal). The bug makes totalSupply > sumBalances.
        assertTrue(c.totalSupply() <= sumBalances);
    }
